const input = $input.first().json;

// Recursively find the object containing our product data
function findProductObject(value) {
  if (!value) return null;

  // If it's already an object, check it
  if (typeof value === "object") {

    // This is the object we're looking for
    if (
      value.name ||
      value.product_name ||
      value.description ||
      value.features
    ) {
      return value;
    }

    // Search nested objects/arrays
    for (const key of Object.keys(value)) {
      const found = findProductObject(value[key]);

      if (found) {
        return found;
      }
    }
  }

  // Gemini may return JSON as a string
  if (typeof value === "string") {

    // Try entire string first
    try {
      const parsed = JSON.parse(value);
      const found = findProductObject(parsed);

      if (found) {
        return found;
      }
    } catch {}

    // Sometimes JSON is surrounded by extra text / markdown
    const start = value.indexOf("{");
    const end = value.lastIndexOf("}");

    if (start !== -1 && end !== -1 && end > start) {
      const possibleJson = value.slice(start, end + 1);

      try {
        const parsed = JSON.parse(possibleJson);
        const found = findProductObject(parsed);

        if (found) {
          return found;
        }
      } catch {}
    }
  }

  return null;
}

const data = findProductObject(input) || {};

// Convert value to text
function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  if (typeof value === "string") {
    return value.trim();
  }

  return String(value).trim();
}

// Convert value to array
function toArray(value) {

  if (Array.isArray(value)) {
    return value
      .filter(v => v !== null && v !== undefined)
      .map(v => String(v).trim())
      .filter(Boolean);
  }

  if (value === null || value === undefined || value === "") {
    return [];
  }

  return [String(value).trim()];
}

// Normalize fields
const product = {
  product_name: toText(
    data.product_name || data.name
  ),

  price: toText(data.price),

  currency: toText(data.currency),

  description: toText(data.description),

  features: toArray(data.features),

  benefits: toArray(data.benefits),

  materials: toArray(data.materials),

  usps: toArray(
    data.usps ||
    data.differentiators ||
    data.unique_selling_points
  ),

  claims: toArray(data.claims),

  target_customer_signals: toArray(
    data.target_customer_signals
  ),

  product_category: toText(
    data.product_category ||
    data.category
  ),

  available_proof: toArray(
    data.available_proof
  ),

  unknown_information: toArray(
    data.unknown_information
  )
};

// Create clean context for future AI nodes
const product_context = `
PRODUCT NAME:
${product.product_name}

PRICE:
${product.price} ${product.currency}

CATEGORY:
${product.product_category}

DESCRIPTION:
${product.description}

FEATURES:
${product.features.map(x => `- ${x}`).join("\n")}

BENEFITS:
${product.benefits.map(x => `- ${x}`).join("\n")}

MATERIALS:
${product.materials.map(x => `- ${x}`).join("\n")}

USPs / DIFFERENTIATORS:
${product.usps.map(x => `- ${x}`).join("\n")}

PRODUCT CLAIMS:
${product.claims.map(x => `- ${x}`).join("\n")}

TARGET CUSTOMER SIGNALS:
${product.target_customer_signals.map(x => `- ${x}`).join("\n")}

AVAILABLE PROOF:
${product.available_proof.map(x => `- ${x}`).join("\n")}

UNKNOWN INFORMATION:
${product.unknown_information.map(x => `- ${x}`).join("\n")}
`.trim();

return [
  {
    json: {
      ...product,
      product_context
    }
  }
];

const input = $input.first().json;

// Get Gemini text response
let text = "";

if (input.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = input.candidates[0].content.parts[0].text;
}

// Clean markdown JSON if Gemini adds ```json
text = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Parse JSON
let result;

try {
  result = JSON.parse(text);
} catch (error) {
  throw new Error(
    "Gemini returned invalid JSON. Raw response:\n" + text
  );
}

// Return clean JSON
return [
  {
    json: result
  }
];

const input = $input.first().json;

// --------------------------------------------------
// 1. Recursively collect all string values
// --------------------------------------------------

function collectStrings(value, results = []) {
  if (typeof value === "string") {
    results.push(value);
    return results;
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      collectStrings(item, results);
    }
    return results;
  }

  if (value && typeof value === "object") {
    for (const key of Object.keys(value)) {
      collectStrings(value[key], results);
    }
  }

  return results;
}

const strings = collectStrings(input);

// --------------------------------------------------
// 2. Find the string containing creative_angles
// --------------------------------------------------

let text = strings.find(
  value =>
    value.includes('"creative_angles"') ||
    value.includes("'creative_angles'") ||
    value.includes("creative_angles")
);

// --------------------------------------------------
// 3. Fallback: if Gemini directly returned an object
// --------------------------------------------------

let result = null;

if (!text) {
  if (
    input.creative_angles &&
    Array.isArray(input.creative_angles)
  ) {
    result = input;
  }
}

// --------------------------------------------------
// 4. Parse the JSON string
// --------------------------------------------------

if (!result && text) {

  // Remove markdown code fences
  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    result = JSON.parse(text);
  } catch (error) {

    // Try extracting the JSON object
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");

    if (start !== -1 && end !== -1) {
      const jsonText = text.slice(start, end + 1);

      try {
        result = JSON.parse(jsonText);
      } catch (secondError) {
        throw new Error(
          "Creative strategy JSON could not be parsed.\n\nRaw Gemini text:\n" +
          text
        );
      }
    }
  }
}

// --------------------------------------------------
// 5. Final validation
// --------------------------------------------------

if (!result) {
  throw new Error(
    "Could not find creative strategy JSON in Gemini response.\n\n" +
    "Available response structure:\n" +
    JSON.stringify(input, null, 2).slice(0, 5000)
  );
}

if (!Array.isArray(result.creative_angles)) {
  throw new Error(
    "Gemini response was found, but creative_angles is missing or is not an array.\n\n" +
    JSON.stringify(result, null, 2).slice(0, 5000)
  );
}

// --------------------------------------------------
// 6. Normalize every angle
// --------------------------------------------------

const creative_angles = result.creative_angles.map(
  (angle, index) => ({
    angle_id: index + 1,

    angle_name: String(
      angle.angle_name || ""
    ).trim(),

    strategic_insight: String(
      angle.strategic_insight || ""
    ).trim(),

    customer_problem: String(
      angle.customer_problem || ""
    ).trim(),

    customer_desire: String(
      angle.customer_desire || ""
    ).trim(),

    why_this_angle_should_work: String(
      angle.why_this_angle_should_work || ""
    ).trim(),

    product_proof: Array.isArray(
      angle.product_proof
    )
      ? angle.product_proof
          .filter(Boolean)
          .map(v => String(v).trim())
      : angle.product_proof
        ? [String(angle.product_proof).trim()]
        : [],

    funnel_stage: String(
      angle.funnel_stage || ""
    ).trim(),

    recommended_format: String(
      angle.recommended_format || ""
    ).trim(),

    creative_direction: String(
      angle.creative_direction || ""
    ).trim(),

    testing_hypothesis: String(
      angle.testing_hypothesis || ""
    ).trim()
  })
);

// --------------------------------------------------
// 7. Return clean structure
// --------------------------------------------------

return [
  {
    json: {
      creative_angles,
      angle_count: creative_angles.length
    }
  }
];

const input = $input.first().json;

// Recursively find a string containing our expected JSON
function findJsonString(obj) {
  if (typeof obj === 'string') {
    if (
      obj.includes('"reviewed_angles"') ||
      obj.includes('"qa_summary"')
    ) {
      return obj;
    }
    return null;
  }

  if (Array.isArray(obj)) {
    for (const item of obj) {
      const found = findJsonString(item);
      if (found) return found;
    }
    return null;
  }

  if (obj && typeof obj === 'object') {
    for (const value of Object.values(obj)) {
      const found = findJsonString(value);
      if (found) return found;
    }
  }

  return null;
}

let rawText = findJsonString(input);

if (!rawText) {
  throw new Error('No Gemini QA JSON response found');
}

// Remove markdown code fences if Gemini added them
rawText = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    'Gemini QA response could not be parsed as JSON: ' +
    error.message
  );
}

// Validate expected structure
if (!parsed.reviewed_angles || !Array.isArray(parsed.reviewed_angles)) {
  throw new Error(
    'Invalid QA output: reviewed_angles array not found'
  );
}

// Normalize each reviewed angle
const reviewedAngles = parsed.reviewed_angles.map((angle, index) => ({
  angle_id: angle.angle_id ?? index + 1,
  angle_name: angle.angle_name ?? '',
  decision: angle.decision ?? 'revise',
  product_relevance: angle.product_relevance ?? '',
  customer_insight_quality: angle.customer_insight_quality ?? '',
  differentiation: angle.differentiation ?? '',
  evidence_support: angle.evidence_support ?? '',
  cliche_risk: angle.cliche_risk ?? '',
  creative_testing_value: angle.creative_testing_value ?? '',
  compliance_check: angle.compliance_check ?? '',
  reason: angle.reason ?? '',
  revision: angle.revision ?? '',
  validated_product_proof: Array.isArray(angle.validated_product_proof)
    ? angle.validated_product_proof
    : [],
  final_creative_direction: angle.final_creative_direction ?? '',
  testing_hypothesis: angle.testing_hypothesis ?? ''
}));

return [
  {
    json: {
      qa_summary: parsed.qa_summary ?? {
        total_angles_reviewed: reviewedAngles.length,
        keep_count: reviewedAngles.filter(a => a.decision === 'keep').length,
        revise_count: reviewedAngles.filter(a => a.decision === 'revise').length,
        reject_count: reviewedAngles.filter(a => a.decision === 'reject').length,
        overall_notes: []
      },
      reviewed_angles: reviewedAngles,
      angle_count: reviewedAngles.length
    }
  }
];

const input = $input.first().json;

const angles = input.reviewed_angles || [];

if (!Array.isArray(angles) || angles.length === 0) {
  throw new Error('No reviewed creative angles found');
}

const rows = [];

for (const angle of angles) {

  // Reject angles ko final testing matrix se exclude karenge
  if (angle.decision === 'reject') {
    continue;
  }

  rows.push({
    json: {
      angle_id: angle.angle_id,
      angle_name: angle.angle_name,

      decision: angle.decision,

      product_relevance: angle.product_relevance,

      customer_insight: angle.customer_insight_quality,

      strategic_differentiation: angle.differentiation,

      evidence_support: angle.evidence_support,

      cliche_risk: angle.cliche_risk,

      creative_testing_value: angle.creative_testing_value,

      compliance_check: angle.compliance_check,

      qa_reason: angle.reason,

      required_revision: angle.revision,

      validated_product_proof:
        Array.isArray(angle.validated_product_proof)
          ? angle.validated_product_proof.join(' | ')
          : '',

      final_creative_direction:
        angle.final_creative_direction,

      testing_hypothesis:
        angle.testing_hypothesis
    }
  });
}

if (rows.length === 0) {
  throw new Error(
    'All creative angles were rejected by QA. No matrix rows available.'
  );
}

return rows;
